308	    /**
309	     * 将调整单纳入批次：仅尚未纳入（batch_id IS NULL）时生效。
310	     *
311	     * @return 1 首次纳入；0 已纳入其他批次（重复纳入不重复计额）
312	     */
313	    public int assignAdjustmentBatch(long adjustmentId, long batchId) {
314	        return jdbcTemplate.update(
315	                "UPDATE refund_adjustment SET batch_id = ? WHERE id = ? AND batch_id IS NULL",
316	                batchId, adjustmentId);
317	    }
318	
319	    // ---- 调账批次 ----
320	
321	    /** 创建开放调账批次（状态 OPEN，版本 1），返回主键。 */
322	    public long insertAdjustmentBatch(String batchNo, String openRequestId, LocalDateTime now) {
323	        KeyHolder keyHolder = new GeneratedKeyHolder();
324	        jdbcTemplate.update(connection -> {
325	            var ps = connection.prepareStatement(
326	                    "INSERT INTO adjustment_batch (batch_no, status, total_cents, adjustment_count,"
327	                            + " version, open_request_id, created_at) VALUES (?,'OPEN',0,0,1,?,?)",
328	                    Statement.RETURN_GENERATED_KEYS);
329	            ps.setString(1, batchNo);
330	            ps.setString(2, openRequestId);
331	            ps.setTimestamp(3, Timestamp.valueOf(now));
332	            return ps;
333	        }, keyHolder);
334	        return keyHolder.getKey().longValue();
335	    }
336	
337	    /** 查询调账批次。 */
338	    public Optional<AdjustmentBatchRow> findAdjustmentBatchByNo(String batchNo) {
339	        return jdbcTemplate.query(batchColumns() + " FROM adjustment_batch WHERE batch_no = ?",
340	                BATCH_MAPPER, batchNo).stream().findFirst();
341	    }
342	
343	    /** 查询调账批次并加行锁。 */
344	    public Optional<AdjustmentBatchRow> findAdjustmentBatchByNoForUpdate(String batchNo) {
345	        return jdbcTemplate.query(batchColumns() + " FROM adjustment_batch WHERE batch_no = ? FOR UPDATE",
346	                BATCH_MAPPER, batchNo).stream().findFirst();
347	    }
348	
349	    /** 按主键查询调账批次。 */
350	    public Optional<AdjustmentBatchRow> findAdjustmentBatchById(long batchId) {
351	        return jdbcTemplate.query(batchColumns() + " FROM adjustment_batch WHERE id = ?",
352	                BATCH_MAPPER, batchId).stream().findFirst();
353	    }
354	
355	    /** 纳入成功后批次调整单数与版本加 1（条件版本防并发覆盖）。 */
356	    public boolean incrementBatchAfterInclude(long batchId, int expectedVersion) {
357	        int rows = jdbcTemplate.update(
358	                "UPDATE adjustment_batch SET adjustment_count = adjustment_count + 1, version = version + 1"
359	                        + " WHERE id = ? AND version = ? AND status = 'OPEN'",
360	                batchId, expectedVersion);
361	        return rows == 1;
362	    }
363	
364	    /** 插入批次负向明细。 */
365	    public void insertBatchDetail(long batchId, long adjustmentId, String txnNo, String lineCode,
366	                                  long signedAmountCents) {
367	        jdbcTemplate.update(
368	                "INSERT INTO adjustment_detail (batch_id, adjustment_id, txn_no, line_code,"
369	                        + " amount_cents, created_at) VALUES (?,?,?,?,?,?)",
370	                batchId, adjustmentId, txnNo, lineCode, signedAmountCents,
371	                Timestamp.valueOf(LocalDateTime.now()));
372	    }
373	
