375	    public List<BatchDetailRow> findBatchDetails(long batchId) {
376	        return jdbcTemplate.query(
377	                "SELECT d.id, d.batch_id, d.adjustment_id, a.adjustment_no, d.txn_no, d.line_code,"
378	                        + " d.amount_cents FROM adjustment_detail d"
379	                        + " JOIN refund_adjustment a ON a.id = d.adjustment_id"
380	                        + " WHERE d.batch_id = ? ORDER BY d.id",
381	                BATCH_DETAIL_MAPPER, batchId);
