93	    @Test
94	    void applyTwoReviewersConfirmAllocateIncludeSealAndOriginalBooksUntouched() throws Exception {
95	        sealedTripAF("t1", "T1", "CARD1");
96	
97	        // 退款前余额查询：由封账实结明细推导
98	        JsonNode balanceBefore = getJson("/api/metro/refunds/balance/T1", 200);
99	        assertEquals(500L, balanceBefore.get("originalFareCents").asLong());
100	        assertEquals(0L, balanceBefore.get("refundedCents").asLong());
101	        assertEquals(500L, balanceBefore.get("availableCents").asLong());
102	
103	        // 申请退款 100 分
104	        JsonNode apply = postJson("/api/metro/refunds/apply", applyBody("ra1", "R1", "T1", 100), 200);
105	        assertEquals("PENDING", apply.get("status").asText());
106	        assertEquals(1, apply.get("version").asInt());
107	
108	        // 首人复核：版本 1 -> 2，单人不生效（无调整单）
109	        JsonNode first = postJson("/api/metro/refunds/confirm",
110	                confirmBody("rc1a", "R1", "U1", "2026-09-26T11:00:00", 1), 200);
111	        assertEquals("IN_REVIEW", first.get("status").asText());
112	        assertEquals(2, first.get("version").asInt());
113	        assertFalse(first.get("confirmed").asBoolean());
114	        assertTrue(first.get("adjustmentNo").isNull());
115	        assertEquals(0, jdbcTemplate.queryForObject(
116	                "SELECT COUNT(*) FROM refund_adjustment", Integer.class));
117	
118	        // 最终确认：不同复核人，版本 2 -> 3，分摊 L1=37、L2=63（尾差按份额降序给 L2）
119	        JsonNode confirmed = postJson("/api/metro/refunds/confirm",
120	                confirmBody("rc1b", "R1", "U2", "2026-09-26T11:05:00", 2), 200);
121	        assertEquals("CONFIRMED", confirmed.get("status").asText());
122	        assertEquals(3, confirmed.get("version").asInt());
123	        assertTrue(confirmed.get("confirmed").asBoolean());
124	        assertEquals("ADJ-R1", confirmed.get("adjustmentNo").asText());
125	        assertEquals("U1", confirmed.get("firstReviewer").asText());
126	        assertEquals("U2", confirmed.get("finalReviewer").asText());
127	        JsonNode allocations = confirmed.get("allocations");
128	        long allocSum = 0;
129	        for (JsonNode a : allocations) {
130	            allocSum += a.get("refundCents").asLong();
131	            if ("L1".equals(a.get("lineCode").asText())) {
132	                assertEquals(37L, a.get("refundCents").asLong());
133	            } else {
134	                assertEquals("L2", a.get("lineCode").asText());
135	                assertEquals(63L, a.get("refundCents").asLong());
136	            }
137	        }
138	        assertEquals(100L, allocSum);
139	
140	        // 负向调整明细独立存在，不触碰原清分明细
141	        Integer negativeDetails = jdbcTemplate.queryForObject(
142	                "SELECT COUNT(*) FROM refund_adjustment_detail WHERE amount_cents < 0", Integer.class);
143	        assertEquals(2, negativeDetails);
144	
145	        // 余额已占用：L1 188/37/151，L2 312/63/249
146	        JsonNode balance = getJson("/api/metro/refunds/balance/T1", 200);
147	        assertEquals(500L, balance.get("originalFareCents").asLong());
148	        assertEquals(100L, balance.get("refundedCents").asLong());
149	        assertEquals(400L, balance.get("availableCents").asLong());
150	        for (JsonNode line : balance.get("lines")) {
151	            switch (line.get("lineCode").asText()) {
152	                case "L1" -> {
153	                    assertEquals(188L, line.get("originalShareCents").asLong());
154	                    assertEquals(37L, line.get("refundedCents").asLong());
155	                    assertEquals(151L, line.get("availableCents").asLong());
156	                }
157	                case "L2" -> {
158	                    assertEquals(312L, line.get("originalShareCents").asLong());
159	                    assertEquals(63L, line.get("refundedCents").asLong());
160	                    assertEquals(249L, line.get("availableCents").asLong());
161	                }
162	                default -> throw new IllegalStateException("unexpected line");
163	            }
164	        }
165	
166	        // 开放调账批次并纳入；重复纳入不重复计额
167	        JsonNode opened = postJson("/api/metro/refunds/batches/open",
168	                "{\"requestId\":\"ro1\",\"batchNo\":\"AB1\",\"openTime\":\"2026-09-26T12:00:00\"}", 200);
169	        assertEquals("OPEN", opened.get("status").asText());
170	        assertEquals(1, opened.get("version").asInt());
171	        JsonNode included = postJson("/api/metro/refunds/batches/include",
172	                "{\"requestId\":\"ri1\",\"adjustmentNo\":\"ADJ-R1\",\"batchNo\":\"AB1\","
173	                        + "\"includeTime\":\"2026-09-26T12:05:00\",\"expectedVersion\":1}", 200);
174	        assertFalse(included.get("alreadyIncluded").asBoolean());
175	        assertEquals(2, included.get("version").asInt());
176	        JsonNode reincluded = postJson("/api/metro/refunds/batches/include",
177	                "{\"requestId\":\"ri1\",\"adjustmentNo\":\"ADJ-R1\",\"batchNo\":\"AB1\","
178	                        + "\"includeTime\":\"2026-09-26T12:05:00\",\"expectedVersion\":1}", 200);
179	        assertTrue(reincluded.get("replayed").asBoolean());
180	        assertEquals(2, reincluded.get("version").asInt());
181	
182	        // 封存：合计 -100，调整单 1
183	        JsonNode sealed = postJson("/api/metro/refunds/batches/seal",
184	                "{\"requestId\":\"rs1\",\"batchNo\":\"AB1\",\"sealTime\":\"2026-09-26T13:00:00\","
185	                        + "\"expectedVersion\":2}", 200);
186	        assertEquals("SEALED", sealed.get("status").asText());
187	        assertEquals(-100L, sealed.get("totalCents").asLong());
188	        assertEquals(1, sealed.get("adjustmentCount").asInt());
189	        assertEquals(3, sealed.get("version").asInt());
190	
191	        JsonNode batchView = getJson("/api/metro/refunds/batches/AB1", 200);
192	        assertEquals(-100L, batchView.get("totalCents").asLong());
193	        assertEquals(1, batchView.get("adjustmentCount").asInt());
194	        assertEquals(2, batchView.get("details").size());
