197	        JsonNode originalBatch = getJson("/api/metro/clearing/batches/2026-09-25", 200);
198	        assertEquals("SEALED", originalBatch.get("status").asText());
199	        assertEquals(500L, originalBatch.get("totalCents").asLong());
200	        assertEquals(1, originalBatch.get("txnCount").asInt());
201	        assertEquals(2, originalBatch.get("details").size());
