252	    @Test
253	    void cumulativeRefundsCannotExceedOriginalAndExactFullIsLegal() throws Exception {
254	        sealedTripAF("t5", "T5", "CARD5");
255	        // 第一笔 300：L1=112，L2=188（尾差给份额更大的 L2）
256	        postJson("/api/metro/refunds/apply", applyBody("ra5a", "R5A", "T5", 300), 200);
257	        postJson("/api/metro/refunds/confirm",
258	                confirmBody("rc5a1", "R5A", "U1", "2026-09-26T11:00:00", 1), 200);
259	        JsonNode first = postJson("/api/metro/refunds/confirm",
260	                confirmBody("rc5a2", "R5A", "U2", "2026-09-26T11:05:00", 2), 200);
261	        assertEquals(112L, first.get("allocations").get(0).get("refundCents").asLong());
262	        assertEquals(188L, first.get("allocations").get(1).get("refundCents").asLong());
