1	package com.example.starter.metro;
2	
3	import java.time.LocalDateTime;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.concurrent.CountDownLatch;
7	import java.util.concurrent.ExecutorService;
8	import java.util.concurrent.Executors;
9	import java.util.concurrent.Future;
10	import java.util.concurrent.TimeUnit;
11	
12	import com.example.starter.metro.dto.AdjustmentBatchOpenRequest;
13	import com.example.starter.metro.dto.EntryRequest;
14	import com.example.starter.metro.dto.ExitRequest;
15	import com.example.starter.metro.dto.RefundApplyRequest;
16	import com.example.starter.metro.dto.RefundConfirmRequest;
17	import com.example.starter.metro.dto.RefundConfirmResponse;
18	import com.example.starter.metro.dto.SealRequest;
19	import org.junit.jupiter.api.AfterEach;
20	import org.junit.jupiter.api.BeforeEach;
21	import org.junit.jupiter.api.Test;
22	import org.springframework.beans.factory.annotation.Autowired;
23	import org.springframework.boot.test.context.SpringBootTest;
24	import org.springframework.jdbc.core.JdbcTemplate;
25	
26	import static org.junit.jupiter.api.Assertions.assertEquals;
27	import static org.junit.jupiter.api.Assertions.assertTrue;
28	
29	/**
30	 * 封账后冲正并发与幂等边界测试（H2 内存库，真实多线程）：
31	 * 并发退款不得超退；并发双人确认恰好一次生成调整单；同键并发只冻结一次结果。
32	 */
33	@SpringBootTest
34	class RefundConcurrencyTest {
35	
36	    @Autowired
37	    private MetroService metroService;
38	
39	    @Autowired
40	    private RefundService refundService;
41	
42	    @Autowired
43	    private JdbcTemplate jdbcTemplate;
44	
45	    private ExecutorService executor;
46	
47	    @BeforeEach
48	    void setUp() {
49	        jdbcTemplate.update("DELETE FROM adjustment_detail");
50	        jdbcTemplate.update("DELETE FROM refund_adjustment_detail");
51	        jdbcTemplate.update("DELETE FROM refund_adjustment");
52	        jdbcTemplate.update("DELETE FROM adjustment_batch");
53	        jdbcTemplate.update("DELETE FROM refund_review");
54	        jdbcTemplate.update("DELETE FROM refund_line_share");
55	        jdbcTemplate.update("DELETE FROM refund_order");
56	        jdbcTemplate.update("DELETE FROM metro_card");
57	        jdbcTemplate.update("DELETE FROM clearing_detail");
58	        jdbcTemplate.update("DELETE FROM clearing_discrepancy");
59	        jdbcTemplate.update("DELETE FROM metro_transaction");
60	        jdbcTemplate.update("DELETE FROM clearing_batch");
61	        jdbcTemplate.update("DELETE FROM idempotency_record");
62	        executor = Executors.newFixedThreadPool(8);
63	    }
64	
65	    @AfterEach
66	    void tearDown() throws InterruptedException {
67	        executor.shutdown();
68	        assertTrue(executor.awaitTermination(10, TimeUnit.SECONDS));
69	    }
70	
71	    /** 构造一笔 A->F、已按实结算并已封账的行程（原实收 500 分，L1=188、L2=312）。 */
72	    private void sealedTripAF(String prefix, String txnNo, String cardId) {
73	        metroService.entry(new EntryRequest(prefix + "-e", txnNo, cardId, "A",
74	                LocalDateTime.of(2026, 9, 25, 9, 0)));
75	        metroService.exit(new ExitRequest(prefix + "-x", txnNo, "F",
76	                LocalDateTime.of(2026, 9, 25, 9, 40)));
77	        metroService.seal(new SealRequest(prefix + "-s", java.time.LocalDate.of(2026, 9, 25)));
78	    }
79	
80	    private <T> List<T> runConcurrently(int threads, java.util.function.IntFunction<T> task)
81	            throws Exception {
82	        CountDownLatch ready = new CountDownLatch(threads);
83	        CountDownLatch start = new CountDownLatch(1);
84	        List<Future<T>> futures = new ArrayList<>();
85	        for (int i = 0; i < threads; i++) {
86	            int index = i;
87	            futures.add(executor.submit(() -> {
88	                ready.countDown();
89	                assertTrue(start.await(5, TimeUnit.SECONDS));
90	                return task.apply(index);
91	            }));
92	        }
93	        assertTrue(ready.await(5, TimeUnit.SECONDS));
94	        start.countDown();
95	        List<T> results = new ArrayList<>();
96	        for (Future<T> future : futures) {
97	            results.add(future.get(20, TimeUnit.SECONDS));
98	        }
99	        return results;
100	    }
101	
