CREATE TABLE IF NOT EXISTS remittance_line (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    statement_id BIGINT NOT NULL,
    line_code VARCHAR(16) NOT NULL,
    due_cents BIGINT NOT NULL,
    paid_cents BIGINT NOT NULL DEFAULT 0,
